CREATE DEFINER=`root`@`localhost` PROCEDURE `GenerateDataPesananMassal` ()   BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE id_dummy INT;
    
    SELECT id_pelanggan INTO id_dummy FROM pelanggan LIMIT 1;
    
    SET FOREIGN_KEY_CHECKS = 0;
    SET AUTOCOMMIT = 0;
    
    WHILE i <= 100000 DO
        VALUES (
            id_dummy,
            DATE_ADD('2026-01-01', INTERVAL FLOOR(RAND() * 365) DAY) + INTERVAL FLOOR(RAND() * 86400) SECOND,
            ELT(FLOOR(1 + (RAND() * 4)), 'baru', 'diproses', 'selesai', 'batal')
        );
        SET i = i + 1;
    END WHILE;
    
    COMMIT;
    SET FOREIGN_KEY_CHECKS = 1;
    SET AUTOCOMMIT = 1;
END$$

